<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php'; require_admin();
$pdo = db(); $id = (int)($_GET['id'] ?? 0); $editing = $id > 0; $errors = [];
$product = ['name'=>'','description'=>'','store'=>'Shopee','category'=>'Geral','price'=>'','price_label'=>'','affiliate_url'=>'','image'=>'','featured'=>0,'active'=>1];
if ($editing) { $stmt=$pdo->prepare('SELECT * FROM products WHERE id=?'); $stmt->execute([$id]); $found=$stmt->fetch(); if (!$found) { http_response_code(404); exit('Produto não encontrado.'); } $product=$found; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 foreach (['name','description','store','category','price_label','affiliate_url'] as $field) $product[$field]=trim((string)($_POST[$field]??''));
 $price=money_input((string)($_POST['price']??'')); $product['price']=$price; $product['featured']=isset($_POST['featured'])?1:0; $product['active']=isset($_POST['active'])?1:0;
 if ($product['name']==='') $errors[]='Informe o nome do produto.';
 if ($product['description']==='') $errors[]='Informe uma descrição.';
 if (!in_array($product['store'],['Shopee','Mercado Livre'],true)) $errors[]='Selecione uma loja válida.';
 if ($price===null && $product['price_label']==='') $errors[]='Informe o preço ou um texto de preço (ex.: A partir de R$ 19,90).';
 if (!filter_var($product['affiliate_url'],FILTER_VALIDATE_URL) || !in_array(parse_url($product['affiliate_url'],PHP_URL_SCHEME),['http','https'],true)) $errors[]='Informe um link de afiliado válido.';
 try { $newImage=upload_image($_FILES['image']??[]); if ($newImage) $product['image']=$newImage; } catch (RuntimeException $e) { $errors[]=$e->getMessage(); }
 if (!$errors) { $data=[$product['name'],$product['description'],$product['store'],$product['category'],$price,$product['price_label'],$product['affiliate_url'],$product['image'],$product['featured'],$product['active']]; if ($editing) { $data[]=$id; $stmt=$pdo->prepare('UPDATE products SET name=?,description=?,store=?,category=?,price=?,price_label=?,affiliate_url=?,image=?,featured=?,active=? WHERE id=?'); } else { $stmt=$pdo->prepare('INSERT INTO products (name,description,store,category,price,price_label,affiliate_url,image,featured,active) VALUES (?,?,?,?,?,?,?,?,?,?)'); } $stmt->execute($data); redirect('admin/index.php'); }
}
$pageTitle=$editing?'Editar produto':'Novo produto'; require __DIR__.'/../includes/header.php';
?><main class="container narrow"><div class="admin-top"><div><span class="eyebrow">CATÁLOGO</span><h1><?= $editing?'Editar produto':'Cadastrar produto' ?></h1></div><a href="<?= e(url('admin/index.php')) ?>">← Voltar</a></div><section class="panel"><?php foreach($errors as $error): ?><p class="alert"><?= e($error) ?></p><?php endforeach; ?><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Nome do produto<input name="name" maxlength="180" required value="<?= e($product['name']) ?>"></label><label>Descrição<textarea name="description" rows="3" required><?= e($product['description']) ?></textarea></label><div class="form-grid"><label>Loja<select name="store"><option <?= $product['store']==='Shopee'?'selected':'' ?>>Shopee</option><option <?= $product['store']==='Mercado Livre'?'selected':'' ?>>Mercado Livre</option></select></label><label>Categoria<input name="category" value="<?= e($product['category']) ?>" placeholder="Ex.: Eletrônicos"></label></div><div class="form-grid"><label>Preço (somente número)<input name="price" inputmode="decimal" placeholder="31,99" value="<?= e((string)($product['price']??'')) ?>"></label><label>Texto alternativo do preço<input name="price_label" placeholder="A partir de R$ 14,90" value="<?= e($product['price_label']) ?>"></label></div><label>Link de afiliado<input type="url" name="affiliate_url" required value="<?= e($product['affiliate_url']) ?>" placeholder="https://..."></label><label>Foto do produto (JPG, PNG ou WEBP, até 4 MB)<input type="file" name="image" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"></label><?php if ($product['image']): ?><p class="muted">Imagem atual: <?= e($product['image']) ?></p><?php endif; ?><label class="check"><input type="checkbox" name="featured" <?= (int)$product['featured']?'checked':'' ?>> Destacar na página inicial</label><label class="check"><input type="checkbox" name="active" <?= (int)$product['active']?'checked':'' ?>> Produto publicado</label><button class="button" type="submit">Salvar produto</button></form></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
